arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) printf '%s\n' "x-access-token" ;;
  *) printf '%s\n' "$GITHUB_TOKEN" ;;
esac
EOF
chmod 700 /tmp/askpass.sh
cd /tmp/friend-chandler && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin friend/chandler 2>&1 | tail -5; echo "exit=$?"; git -C /tmp/friend-chandler log --oneline -1
